import os
import tomllib

class ConfigError(Exception):
    pass

def load_config(defaults, toml_path=None, env_prefix='', env=None):
    if env is None:
        env = os.environ
    config = defaults.copy()
    if toml_path:
        try:
            with open(toml_path, 'rb') as f:
                toml_config = tomllib.load(f)
                config.update(tomllib.load(f))
        except FileNotFoundError:
            pass
    for key, value in env.items():
        if key.startswith(env_prefix):
            path = key[len(env_prefix):].lower().split('__')
            current = config
            for part in path[:-1]:
                if part not in current:
                    current[part] = {}
                current = current[part]
            current[path[-1]] = value
    return config

import pytest
from envcfg import load_config, ConfigError

def test_defaults():
    defaults = {'a': 1, 'b': 2}
    assert load_config(defaults) == {'a': 1, 'b': 2}

def test_toml():
    with open('config.toml', 'wb') as f:
        f.write(b'a = 3\nb = 4')
    defaults = {'a': 1, 'b': 2}
    assert load_config(defaults, 'config.toml') == {'a': 3, 'b': 4}

def test_env():
    os.environ['APP__A'] = '5'
    defaults = {'a': 1, 'b': 2}
    assert load_config(defaults, env_prefix='APP__') == {'a': 5, 'b': 2}

def test_nested():
    os.environ['APP__SERVER__PORT'] = '8080'
    defaults = {'server': {'port': 80}}
    assert load_config(defaults, env_prefix='APP__') == {'server': {'port': 8080}}

def test_coercion():
    os.environ['APP__A'] = '6'
    defaults = {'a': 1}
    assert load_config(defaults, env_prefix='APP__') == {'a': 6}

def test_error():
    os.environ['APP__A'] = 'seven'
    defaults = {'a': 1}
    with pytest.raises(ConfigError):
        load_config(defaults, env_prefix='APP__')

